await T('Necroblossom Snarl',async()=>{const g=fresh();const [a]=g.players;const s1=C('Necroblossom Snarl');a.hand=[s1,L('Forest')];await g.playLand(a,s1);ok('Necroblossom Snarl: Forest in hand -> untapped',!a.battlefield.find(x=>x.card===s1).tapped);const g2=fresh();const [a2]=g2.players;const s2=C('Necroblossom Snarl');a2.hand=[s2,L('Island'),L('Mountain')];await g2.playLand(a2,s2);ok('Necroblossom Snarl: no Swamp/Forest -> tapped',a2.battlefield.find(x=>x.card===s2).tapped);const g3=fresh();const [a3]=g3.players;const s3=C('Necroblossom Snarl');a3.hand=[s3,L('Swamp')];await g3.playLand(a3,s3);ok('Necroblossom Snarl: Swamp in hand -> untapped',!a3.battlefield.find(x=>x.card===s3).tapped);});

