await T('Firion, Wild Rose Warrior',async()=>{const g=fresh();const [a]=g.players;put(g,a,C('Firion, Wild Rose Warrior'));const eqC=S('Blade','Artifact — Equipment','{2}','Equipped creature gets +1/+1.\nEquip {3}',2);const pm=await g.enterPerm(a,eqC);await g.permEntered(a,pm);await flush(g);const tk=a.battlefield.filter(x=>x.card.token&&/Blade/.test(x.card.name));ok('Firion: nontoken Equipment -> token copy',tk.length===1,String(tk.length));if(tk.length){const eab=(tk[0].card.abilities||[]).find(z=>z.label==='equip');const cost=eab?g.abilityCost(a,tk[0].card,eab,tk[0]):null;ok("Firion: token's equip costs {2} less (3 -> 1)",cost&&cost.total===1,cost?String(cost.total):'no equip');await g.cleanup(a);ok('Firion: token not sacrificed at end of this turn (only at next upkeep)',a.battlefield.includes(tk[0]));}
 const n0=a.battlefield.filter(x=>x.card.token).length;const tkEq={...S('Blade','Artifact — Equipment','{2}','Equipped creature gets +1/+1.\nEquip {3}',2),token:true};const pm2=await g.enterPerm(a,tkEq);await g.permEntered(a,pm2);await flush(g);ok('Firion: token Equipment entering -> no copy',a.battlefield.filter(x=>x.card.token).length===n0+1);const pm3=await g.enterPerm(a,art('Rock'));await g.permEntered(a,pm3);await flush(g);ok('Firion: non-Equipment artifact -> no copy',a.battlefield.filter(x=>x.card.token).length===n0+1);});

