await T('Twilight Diviner',async()=>{const g=fresh();const [a]=g.players;put(g,a,C('Twilight Diviner'));const h=await g.enterPerm(a,S('Handy','Creature — Elk','{2}','',2,2,2));await g.creatureEntered(a,h);await flush(g);ok('Twilight Diviner: creature from hand -> no copy',toks(a).length===0);const z=S('Zed','Creature — Zombie','{2}','',2,3,3);a.graveyard.push(z);await g.runOps(a,[{op:'reanim',filter:'creature'}],{name:'Raise'},{});await flush(g);ok('Twilight Diviner: creature from graveyard -> token copy',toks(a,/Zed/).length===1,String(toks(a).length));const z2=S('Zed2','Creature — Zombie','{2}','',2,3,3);a.graveyard.push(z2);await g.runOps(a,[{op:'reanim',filter:'creature'}],{name:'Raise'},{});await flush(g);ok('Twilight Diviner: only once each turn',toks(a,/Zed2/).length===0);
 const g2=fresh();const [a2]=g2.players;quiet(g2);put(g2,a2,C('Twilight Diviner'));const z3=S('Zed3','Creature — Zombie','{2}','',2,3,3);a2.graveyard.push(z3);const rs=S('Rise','Sorcery','{2}{B}','Return target creature card from your graveyard to the battlefield.',3);a2.hand=[rs];W(g2,a2,3,'Swamp');await g2.cast(a2,rs,'hand');await flush(g2);ok('Twilight Diviner: reanimation spell -> copy',a2.battlefield.some(x=>x.card===z3)&&toks(a2,/Zed3/).length===1,`${a2.battlefield.some(x=>x.card===z3)} ${toks(a2).length}`);});

// ---------------- Moon-Circuit Hacker
