await T('Moon-Circuit Hacker',async()=>{const g=fresh();const [a,b]=g.players;const mh=put(g,a,C('Moon-Circuit Hacker'));mh.enteredTurn=g.turn-1;a.hand=[L('Forest'),L('Forest')];const h0=a.hand.length;await cd(g,a,b,mh,2);ok('Moon-Circuit Hacker: not entered this turn -> draw then discard (net 0)',a.hand.length===h0,String(a.hand.length-h0));const g2=fresh();const [a2,b2]=g2.players;const mh2=put(g2,a2,C('Moon-Circuit Hacker'));mh2.enteredTurn=g2.turn;a2.hand=[L('Forest')];const h2=a2.hand.length;await cd(g2,a2,b2,mh2,2);ok('Moon-Circuit Hacker: entered this turn -> draw, no discard',a2.hand.length===h2+1,String(a2.hand.length-h2));});

// ---------------- Mangara
await T('Mangara, the Diplomat',async()=>{const g=fresh();const [a,b,c]=g.players;put(g,a,C('Mangara, the Diplomat'));const x1=put(g,b,bear()),x2=put(g,b,bear());g.active=1;let h0=a.hand.length;await g.attackTriggers(b,[{attacker:x1,defender:a}]);await flush(g);ok('Mangara: one attacker -> no draw',a.hand.length===h0);h0=a.hand.length;await g.attackTriggers(b,[{attacker:x1,defender:a},{attacker:x2,defender:c}]);await flush(g);ok('Mangara: two attackers split between players -> no draw',a.hand.length===h0);h0=a.hand.length;await g.attackTriggers(b,[{attacker:x1,defender:a},{attacker:x2,defender:a}]);await flush(g);ok('Mangara: two attackers at you -> draw',a.hand.length===h0+1);const g2=fresh();const [a2,b2,c2]=g2.players;put(g2,a2,C('Mangara, the Diplomat'));const y1=put(g2,b2,bear()),y2=put(g2,b2,bear());g2.active=1;const h2=a2.hand.length;await g2.attackTriggers(b2,[{attacker:y1,defender:c2},{attacker:y2,defender:c2}]);await flush(g2);ok('Mangara: two attackers at another player -> no draw',a2.hand.length===h2);});

