await T('Mask of Memory',async()=>{const g=fresh();const [a,b]=g.players;const mm=put(g,a,C('Mask of Memory'));const x=put(g,a,bear());mm.attachedTo=x.id;a.hand=[L('Forest')];const h0=a.hand.length,l0=a.library.length;await cd(g,a,b,x,2);ok('Mask of Memory: equipped creature hits -> draw 2',a.library.length===l0-2);ok('Mask of Memory: then discard 1 (net +1)',a.hand.length===h0+1,String(a.hand.length-h0));const y=put(g,a,bear());const h1=a.hand.length,l1=a.library.length;await cd(g,a,b,y,2);ok('Mask of Memory: unequipped creature -> nothing',a.hand.length===h1&&a.library.length===l1);});

// ---------------- Frenzied Baloth
// ENGINE BUG: noCounter ['creature'] matches every spell (matchesFilter)
await T('Frenzied Baloth: counters',async()=>{const cancel=()=>S('Cancel','Instant','{1}{U}{U}','Counter target spell.',3);const run=async(caster,card)=>{const g=fresh();const [a,b]=g.players;quiet(g);put(g,a,C('Frenzied Baloth'));const cc=g.players[caster];const v=spell(g,cc,card);const ctr=cancel();const counterer=caster===0?b:a;counterer.hand=[ctr];W(g,counterer,3,'Island');await g.cast(counterer,ctr,'hand',{spell:v},{instant:true});await flush(g);return !!v.countered;};
 ok("Frenzied Baloth: the Baloth spell can't be countered",!(await (async()=>{const g=fresh();const [a,b]=g.players;quiet(g);const v=spell(g,a,C('Frenzied Baloth'));const ctr=cancel();b.hand=[ctr];W(g,b,3,'Island');await g.cast(b,ctr,'hand',{spell:v},{instant:true});await flush(g);return !!v.countered;})()));
 ok("Frenzied Baloth: my other creature spell can't be countered",!(await run(0,bear())));
 ok('Frenzied Baloth: my noncreature spell CAN be countered',await run(0,S('Divvy','Sorcery','{2}{U}','Draw two cards.',3)));
 ok("Frenzied Baloth: opponent's creature spell CAN be countered",await run(1,bear()));});
// ENGINE BUG: noCombatPrevent static never read; fogTurn ends combat unconditionally
await T("Frenzied Baloth: combat damage can't be prevented",async()=>{const g=fresh();const [a,b]=g.players;quiet(g);put(g,a,C('Frenzied Baloth'));const x=put(g,a,bear());b.ai.chooseBlocks=()=>new Map();g.phase='combat';g.fogTurn=g.turn;const l0=b.life;await g.combatPhase(a,[{attacker:x,defender:b}]);ok("Frenzied Baloth: fog doesn't prevent combat damage",l0-b.life===2,String(l0-b.life));const g2=fresh();const [a2,b2]=g2.players;quiet(g2);const x2=put(g2,a2,bear());b2.ai.chooseBlocks=()=>new Map();g2.phase='combat';g2.fogTurn=g2.turn;const l2=b2.life;await g2.combatPhase(a2,[{attacker:x2,defender:b2}]);ok('Frenzied Baloth: (control) without Baloth fog prevents',l2===b2.life);});

